create table public.order_items (id uuid primary key default gen_random_uuid(), store_id uuid not null, order_id uuid not null, variant_id uuid, sku_snapshot text not null, product_name_snapshot text not null, variant_name_snapshot text, quantity integer not null check(quantity > 0), unit_price_minor bigint not null check(unit_price_minor >= 0), tax_minor bigint not null default 0 check(tax_minor >= 0), discount_minor bigint not null default 0 check(discount_minor >= 0), line_total_minor bigint not null check(line_total_minor >= 0), created_at timestamptz not null default now(), foreign key(store_id,order_id) references public.orders(store_id,id) on delete cascade, foreign key(store_id,variant_id) references public.product_variants(store_id,id) on delete set null (variant_id), unique(store_id,id));
